-- =============================================================================
-- 120 CAMBRIDGE IGCSE CATALOGUE — every Cambridge IGCSE syllabus with its
-- published syllabus documents, and the grades each school syllabus is taught in.
--
-- Source: database/data/cambridge-igcse-syllabuses.csv (Cambridge International's
-- list of latest syllabuses and the syllabus for 2026 exams). `documents` holds each
-- published syllabus with the exam years it covers; the API picks, per grade, the
-- document for the year that grade sits its exams (Grade 10 this academic year,
-- Grade 9 the year after). 9-1 syllabuses are listed for reference — the school's
-- grade scale is A*-G.
--
-- Re-running is safe: rows are upserted by code. To refresh, regenerate the VALUES
-- from a newer CSV in a new migration.
-- =============================================================================
CREATE TABLE cambridge_igcse_catalogue (
  code          text PRIMARY KEY CHECK (code ~ '^[0-9]{4}$'),
  subject       text NOT NULL,
  grading       text NOT NULL CHECK (grading IN ('A*-G', '9-1')),
  documents     jsonb NOT NULL DEFAULT '[]'::jsonb,   -- [{label, from, to, url}], newest first
  subject_page  text,
  updated_at    timestamptz NOT NULL DEFAULT now()
);


ON CONFLICT (code) DO UPDATE SET subject = EXCLUDED.subject, grading = EXCLUDED.grading,
  documents = EXCLUDED.documents, subject_page = EXCLUDED.subject_page, updated_at = now();

-- Which grades take each school syllabus: usually Grades 9 and 10 (a two-year course);
-- some schools start in Grade 8.
ALTER TABLE syllabuses ADD COLUMN grade_levels int[] NOT NULL DEFAULT '{9,10}'
  CHECK (cardinality(grade_levels) BETWEEN 1 AND 3 AND grade_levels <@ ARRAY[8, 9, 10]);
